import { index, numeric, pgEnum, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { user } from "@/app/lib/db/schema";

export const chatMessageRole = pgEnum("chat_message_role", ["user", "assistant"]);

// Transcripts outlive their users: deleting an account clears the link but keeps the messages.
export const chatConversations = pgTable(
  "chat_conversations",
  {
    // Generated by the browser when a chat starts.
    id: uuid("id").primaryKey(),
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (table) => [index("chat_conversations_user_id_idx").on(table.userId)],
);

export const chatMessages = pgTable(
  "chat_messages",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    conversationId: uuid("conversation_id")
      .notNull()
      .references(() => chatConversations.id, { onDelete: "cascade" }),
    // Copied from the conversation so the daily limit is one indexed count.
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    role: chatMessageRole("role").notNull(),
    content: text("content").notNull(),
    // Set on assistant messages: the exact OpenRouter charge for the reply.
    costUsd: numeric("cost_usd", { precision: 12, scale: 8 }),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (table) => [
    index("chat_messages_conversation_id_idx").on(table.conversationId),
    index("chat_messages_user_id_created_at_idx").on(table.userId, table.createdAt),
    index("chat_messages_created_at_idx").on(table.createdAt),
  ],
);
